"""Temporary exact-tree review-branch transport; never write main."""
import base64
import gzip
import json
import os
from pathlib import Path
import subprocess

BRANCH = 'overhaul/source-review-2026-11-16'
MAIN = '1f757a012d0831f97f5e56dbea68b5f76999ffd3'
REVIEW = 'b0faa5a150e97733ddce4dc3201ce115717521d2'
EXPECTED_DATA = '410e3d94e0c0801ac61c572a9a0134f3b025d397'
EXPECTED_BENCHMARKS = 'a005fb7936c3006f6da70ed002059517cc1b7f78'
REVIEW_GENERATION_TIME = '2026-11-24T17:13:07.730030'
EVIDENCE_GZIP = ''

def git(*args):
    return subprocess.check_output(['git', *args], text=True).strip()

def remote(branch):
    return git('ls-remote', 'origin', 'refs/heads/' + branch).split()[0]

assert os.environ['GITHUB_REPOSITORY'] == 'OpenSourcePatents/Congresswatch'
assert os.environ['GITHUB_REF'] == 'refs/heads/' + BRANCH
head = os.environ['GITHUB_SHA']
assert git('rev-parse','HEAD') == head and git('rev-parse','HEAD^') == REVIEW
assert remote(BRANCH) == head and remote('main') == MAIN
Path('benchmarks/nov24-finance-run-evidence.json').write_bytes(gzip.decompress(base64.b64decode(EVIDENCE_GZIP)))
for i in range(2):
    result = json.loads(subprocess.check_output(['python','validation/reconcile_nov24_finance.py'],text=True))
    if i == 1:
        assert result['changed_files'] == 0
for script in ('recompute_scores.py','build_aggregates.py','audit_data.py'):
    subprocess.run(['python',script],check=True,stdout=subprocess.DEVNULL)
# Replay the locally reviewed generation timestamp exactly. Source attempt and
# last-good retrieval timestamps are untouched; this is not a new source fetch.
paths = list(Path('data/details').glob('*.json')) + [Path('data/members.json')]
for path in paths:
    obj = json.loads(path.read_text())
    rows = obj if isinstance(obj,list) else [obj]
    if path.name != 'members.json' and path.stem not in {m['id'] for m in json.loads(Path('data/members.json').read_text())}:
        continue
    for row in rows:
        row['score_updated'] = REVIEW_GENERATION_TIME
    path.write_text(json.dumps(obj,indent=2))
p = Path('data/stats.json'); obj=json.loads(p.read_text()); obj['last_updated']=REVIEW_GENERATION_TIME;p.write_text(json.dumps(obj,indent=2))
subprocess.run(['git','add','--','data','benchmarks/nov24-finance-run-evidence.json','benchmarks/nov24-finance-reconciliation.json'],check=True)
tree = git('write-tree')
assert git('rev-parse',tree+':data') == EXPECTED_DATA
assert git('rev-parse',tree+':benchmarks') == EXPECTED_BENCHMARKS
assert remote(BRANCH) == head and remote('main') == MAIN
message = 'Reconcile bounded finance observations and preserve verified scoring gates'
commit = subprocess.check_output(['git','-c','user.name=CongressWatch review reconciliation','-c','user.email=41898282+github-actions[bot]@users.noreply.github.com','commit-tree',tree,'-p',head,'-p',MAIN],input=message+'\n',text=True).strip()
subprocess.run(['git','push','origin',commit+':refs/heads/'+BRANCH],check=True)
print(json.dumps({'head':commit,'tree':tree,'data_tree':EXPECTED_DATA,'benchmarks_tree':EXPECTED_BENCHMARKS,'main_still_current':remote('main')==MAIN}))
